input.function:
() => {
  const click = id => { const e = document.getElementById(id); if (!e.checked) e.click(); return e.checked; };
  click('registration_intending_to_team_up_working_solo');
  click('registration_source_devpost');
  const med = document.getElementById('registration_source_medium_devpost.com_10'); if (med && med.offsetParent) med.click();
  const org = document.getElementById('registration_registration_field_values_attributes_0_value'); org.value = 'ORANO AI'; org.dispatchEvent(new Event('input',{bubbles:true}));
  const vals = {1:'Yes',2:'No',3:'Yes',4:'Yes'};
  for (const [i,v] of Object.entries(vals)) { const s = document.getElementById(`registration_registration_field_values_attributes_${i}_value`); s.value = v; if (window.jQuery) jQuery(s).trigger('change'); else s.dispatchEvent(new Event('change',{bubbles:true})); }
  click('registration_agree_to_eligibility'); click('registration_agree_to_rules');
  return [...document.querySelectorAll('form select')].map(s=>s.value).concat([org.value, document.getElementById('registration_agree_to_rules').checked, document.getElementById('registration_agree_to_eligibility').checked]);
}

