input.function:
() => {
  const lab = id => { const l = document.querySelector(`label[for="${id}"]`); (l||document.getElementById(id)).click(); return document.getElementById(id).checked; };
  const r = {solo: lab('registration_intending_to_team_up_working_solo'), src: lab('registration_source_devpost')};
  const org = document.getElementById('registration_registration_field_values_attributes_0_value'); if (!org.value) org.value = 'ORANO AI';
  r.selects = [...document.querySelectorAll('form select')].map(s=>s.value);
  r.elig = document.getElementById('registration_agree_to_eligibility').checked || lab('registration_agree_to_eligibility');
  r.rules = document.getElementById('registration_agree_to_rules').checked || lab('registration_agree_to_rules');
  r.org = org.value;
  r.medVisible = [...document.querySelectorAll('[name="registration[source_medium]"]')].filter(e=>e.offsetParent).map(e=>e.id);
  return r;
}

